-- Q8390: Tax-Exempt Organizations [medium/L2]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["$20 per day, capped at the lesser of $10,500 or 5% of gross receipts","$100 per day with no maximum cap on the total accumulated penalty","A flat penalty of $500 regardless of how many days the return is late","No penalty because tax-exempt organizations are exempt from filing penalties"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (A): Under IRC Section 6652(c)(1)(A), organizations with gross receipts under $1,186,000 face a penalty of $20 per day the return is late, up to the lesser of $10,500 or 5% of gross receipts. For $400,000 in gross receipts, the cap is $10,500.
