  choices = $EXPL$["The expenditure is permitted because it supports the foundation''s educational purpose","The expenditure is subject to the same substantial-part test as public charities","The $50,000 is a taxable expenditure with a 20% excise tax under Section 4945","The expenditure triggers automatic revocation of the foundation''s exempt status"]$EXPL$::jsonb,
