  choices = $EXPL$["It eliminates the prohibition on political campaign activity for the organization","It permits unlimited lobbying expenditures as long as they are properly documented","It replaces the vague substantial-part test with specific dollar-limit safe harbors","It converts lobbying expenses into deductible charitable contributions for donors"]$EXPL$::jsonb,
